525	        // 与装载/封舱/到达保持一致的加锁顺序，避免跨操作锁倒置死锁。
526	        BagRow preview = findBag(request.bagTag());
527	        if (preview == null) {
528	            throw ApiException.notFound("行李不存在: " + request.bagTag());
529	        }
530	        LegRow loadedLeg = null;
531	        if (preview.loadedLegId() != null) {
532	            loadedLeg = lockLeg(preview.loadedLegId());
533	        }
534	        BagRow bag = lockBag(request.bagTag());
535	        if (bag == null) {
536	            throw ApiException.notFound("行李不存在: " + request.bagTag());
537	        }
538	        if (findHold(request.holdKey()) != null) {
539	            throw ApiException.conflict("holdKey 已存在: " + request.holdKey());
540	        }
541	        if (BAG_DELIVERED.equals(bag.status())) {
542	            throw ApiException.conflict("行李 " + bag.bagTag() + " 已到达最终目的地，不得暂扣");
543	        }
544	        if (BAG_SHORT_UNLOADED.equals(bag.status())) {
545	            throw ApiException.conflict("行李 " + bag.bagTag() + " 已短卸丢失，不得暂扣");
546	        }
547	        if (BAG_CUSTOMS_HOLD.equals(bag.status())) {
548	            throw holdConflict(bag);
549	        }
550	        String previousStatus = bag.status();
